const b = $json;

const planDays         = Number(b.planDays || 7);
const people           = Number(b.people || 1);
const mealsPerDay      = Array.isArray(b.mealsPerDay)     ? b.mealsPerDay     : (b.mealsPerDay     ? [b.mealsPerDay]     : ["breakfast","lunch","dinner"]);
const cuisine          = Array.isArray(b.cuisine)          ? b.cuisine          : (b.cuisine          ? [b.cuisine]          : []);
const allergies        = Array.isArray(b.allergies)        ? b.allergies        : (b.allergies        ? [b.allergies]        : []);
const avoidIngredients = Array.isArray(b.avoidIngredients) ? b.avoidIngredients : (b.avoidIngredients ? [b.avoidIngredients] : []);

const goal          = b.goal        || "balanced";
const budgetLevel   = b.budgetLevel || "medium";
const budgetTotal   = b.budgetTotal ? `$${b.budgetTotal}/week` : "";
const timePerMeal   = Number(b.timePerMeal || 30);
const calorieTarget = b.calorieTarget ? String(b.calorieTarget) : "";
const notes         = b.notes || "";

// FIX 1: macroTargets was never read — now passed to AI prompt
const macroTargets = b.macroTargets || {};
const macroLine = [
  macroTargets.protein ? `${macroTargets.protein}g protein` : "",
  macroTargets.carbs   ? `${macroTargets.carbs}g carbs`     : "",
  macroTargets.fat     ? `${macroTargets.fat}g fat`         : ""
].filter(Boolean).join(", ");

// FIX 2: dietStyle was ghost field — derive from goal instead
const dietStyle = goal.includes("diabetic")   ? "diabetic-friendly"
               : goal.includes("vegan")        ? "vegan"
               : goal.includes("vegetarian")   ? "vegetarian"
               : goal.includes("keto")         ? "keto"
               : goal.includes("heart")        ? "heart-healthy"
               : "";

// FIX 3: macroSummary added — genie sidebar reads result.macroSummary
// FIX 4: days label field added — genie reads d.label for Monday/Tuesday headers
// FIX 5: groceryList categories aligned to genie grocery planner groupings
const schema = {
  planMeta: {
    days: planDays,
    people,
    goal,
    dietStyle,
    mealsPerDay,
    cuisine,
    allergies,
    avoidIngredients,
    budgetLevel,
    timePerMealMinutes: timePerMeal,
    calorieTarget,
    notes
  },
  macroSummary: {
    protein: 0,
    carbs: 0,
    fat: 0,
    calories: 0,
    note: "Average per person per day across all meals"
  },
  groceryList: [
    {
      item: "string",
      quantity: "string",
      category: "Produce|Protein|Dairy|Pantry|Frozen|Bakery|Snacks|Drinks|Household|Other"
    }
  ],
  days: [
    {
      day: 1,
      label: "Monday",
      meals: [
        {
          mealType: "breakfast|lunch|dinner|snack|morning_snack|afternoon_snack",
          title: "string",
          cuisine: "string",
          prepTimeMinutes: 10,
          cookTimeMinutes: 15,
          servings: people,
          ingredients: [{ name: "string", amount: "string" }],
          steps: ["string"],
          nutrition: {
            calories: 0,
            protein_g: 0,
            carbs_g: 0,
            fat_g: 0,
            fiber_g: 0,
            sugar_g: 0
          },
          diabeticNotes: ""
        }
      ]
    }
  ]
};

const userPrompt = `Create a ${planDays}-day meal plan for ${people} ${people === 1 ? "person" : "people"}.

Constraints:
- Goal: ${goal}
- Diet style: ${dietStyle || "none specified"}
- Meals per day: ${mealsPerDay.join(", ")}
- Cuisine preferences: ${cuisine.length ? cuisine.join(", ") : "no preference"}
- Allergies / intolerances: ${allergies.length ? allergies.join(", ") : "none"}
- Avoid ingredients: ${avoidIngredients.length ? avoidIngredients.join(", ") : "none"}
- Budget: ${budgetLevel}${budgetTotal ? ` (${budgetTotal} total for ${people} ${people === 1 ? "person" : "people"})` : ""}
- Max time per meal: ${timePerMeal} minutes
- Daily calorie target per person: ${calorieTarget || "not specified"}
- Macro targets per person per day: ${macroLine || "not specified"}
- Additional notes: ${notes || "none"}

Output requirements:
- Return ONLY valid JSON. No markdown. No preamble. No trailing text.
- The first character must be { and the last must be }.
- Match this exact JSON structure and fill every field with real values:
${JSON.stringify(schema, null, 2)}

Rules:
- label field on each day must be the weekday name: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday (repeat cycle if planDays > 7).
- macroSummary must contain the AVERAGE per-person per-day totals calculated across ALL meals in the plan.
- groceryList categories must be exactly one of: Produce, Protein, Dairy, Pantry, Frozen, Bakery, Snacks, Drinks, Household, Other.
- Reuse ingredients across the week to keep the grocery list short and reduce cost.
- diabeticNotes: fill only when goal is diabetic-friendly, otherwise use empty string "".
- For diabetic-friendly plans: use low-GI ingredients, avoid added sugar, include fibre-rich options.
- servings on every meal must equal ${people}.
`;

return [{ userPrompt, planDays, people }];

const raw = $json;

// Langchain v2.1 node outputs to output_text — check that first
const content =
  raw.output_text ||
  raw.message?.content ||
  raw.choices?.[0]?.message?.content ||
  raw.text ||
  "";

// Attempt 1: direct parse
try {
  const parsed = JSON.parse(content);
  return [{ ok: true, result: parsed }];
} catch (e) {}

// Attempt 2: strip markdown fences
const stripped = content.replace(/```json|```/gi, "").trim();
try {
  const parsed = JSON.parse(stripped);
  return [{ ok: true, result: parsed }];
} catch (e) {}

// Attempt 3: extract outermost JSON object
const match = stripped.match(/\{[\s\S]*\}/);
if (match) {
  try {
    const parsed = JSON.parse(match[0]);
    return [{ ok: true, result: parsed }];
  } catch (e) {}
}

// All attempts failed — return diagnostic
return [{
  ok: false,
  result: {
    error: "Model output was not valid JSON",
    hint: "Check maxTokens is high enough (try 6000). Confirm system prompt is plain text not JS code.",
    rawLength: content.length,
    rawPreview: content.slice(0, 500)
  }
}];
